mapper.select:
SELECT item_id, batch_id, exchange_id, result, processed_at, failure_code, failure_message
FROM settlement_item
WHERE item_id = #{itemId}

SELECT EXISTS (
    SELECT 1 FROM settlement_item WHERE exchange_id = #{exchangeId} AND result = 'SUCCESS'
)

SELECT EXISTS (
    SELECT 1 FROM settlement_item WHERE exchange_id = #{exchangeId} AND result IS NULL
)
